<!--
  GearSwap Atelier · the control of a Modules setting (modules.ts ModCtl): buttons for a choice (an "auto" one with its
  field to force a value), a switch, a number (- / +, a slider, its standard value), a colour and the ready-made ones,
  a text field, a list of tiles, a table of lines, the setting as written when the page cannot change it. The controls
  keep the attributes the old handlers read (data-modfile, data-modpath, data-modopt, data-mcchoice, data-modin,
  data-modbool, data-moddrag, data-moddel, data-modpick, data-modaddv, data-modadd, data-rowcell, data-rowup / down /
  del, data-rowadd).

  @file    atelier/src/screens/config/ModCtl.svelte
  @author  ejouanchicot
-->
<script lang="ts">
  import {selSync} from '../../components/selsync';
  import type {ModCtl as Ctl} from './modules';

  import ModCtl from './ModCtl.svelte';
  import GearList from './GearList.svelte';

  let {c}: {c: Ctl} = $props();
</script>

{#snippet step(c: Extract<Ctl, {k: 'num'}>, i: number)}{@const b = c.steps[i]!}<button class="mcstep" data-numstep={b.step} {...c.lim} {...c.id} disabled={c.off} title={b.tip} aria-label={b.aria}>{b.sign}</button>{/snippet}

{#if c.k === 'seg'}<span class="modseg">{#each c.btns as b, i (i)}<button {...b.attrs} {...c.id} aria-pressed={b.pressed} disabled={c.off} title={b.tip}>{b.label}</button>{/each}</span>{#if c.input}<input class="modin num" type="text" value={c.input.value} placeholder={c.input.ph} {...c.id} data-modin disabled={c.off} title={c.input.tip}>{/if}{:else if c.k === 'switch'}<button class="modsw" role="switch" aria-checked={c.on} {...c.id} data-modbool disabled={c.off} title={c.tip}><span class="sw {c.on ? 'on' : ''}" aria-hidden="true"></span><b>{@html c.labelHtml}</b></button>{:else if c.k === 'text'}<input class="modin" type="text" value={c.value} {...c.id} data-modin disabled={c.off} title={c.tip}>{:else if c.k === 'num'}{#if c.slide}<input class="modrange" type="range" min={c.slide.min} max={c.slide.max} step={c.slide.step} value={c.value} data-modrange {...c.id} disabled={c.off} title={c.slide.tip}>{/if}<span class="mcfield">{@render step(c, 0)}<input class="modin num" type="text" inputmode="decimal" value={c.value} {...c.lim} {...c.id} data-modin disabled={c.off} title={c.tip}>{#if c.unit}<i class="mcunit">{c.unit}</i>{/if}{@render step(c, 1)}</span>{#if c.std}{#if c.std.is}<small class="mcstd is">{c.std.text}</small>{:else}<button class="mcstd" data-modstd={c.std.v} {...c.id} disabled={c.off} title={c.std.tip}>{c.std.text}</button>{/if}{/if}{:else if c.k === 'color'}<span class="modcolor"><input type="color" value={c.hex} {...c.attrs} disabled={c.off} title={c.tip}><code>{c.hex.toUpperCase()}</code><small>{c.of}</small></span>{:else if c.k === 'presets'}<div class="modpresets"><small>{c.label}</small>{#each c.tiles as p, i (i)}<button class="modpreset" {...p.attrs} aria-pressed={p.pressed} disabled={c.off} title={p.tip}><i style={p.style}></i><span>{p.name}</span></button>{/each}</div>{:else if c.k === 'chips'}<div class="modchips">{#each c.tiles as x, i (i)}<span class="modchip {c.pic ? 'item' : ''}" draggable={c.off ? undefined : 'true'} data-moddrag={i} {...c.id} title={c.dragTip}>{#if c.pic}{@html x.icoHtml}{:else}<i class="mcnum">{i + 1}</i>{/if}<span class="mcn {x.modeTip ? 'mode' : ''}" title={x.modeTip || undefined}>{x.label}</span><button data-moddel={i} {...c.id} disabled={c.off} title={x.del} aria-label={x.del}>×</button></span>{/each}{#if c.add.k === 'pick'}<button class="modaddbtn" {...c.add.attrs} {...c.id} disabled={c.off} title={c.add.tip}>{c.add.label}</button>{:else if c.add.k === 'bags'}{#each c.add.list as b (b.b)}<button class="modaddbtn" data-modaddv={b.b} {...c.id} disabled={c.off} title={b.tip}>{'+ ' + b.b}</button>{/each}{:else}<input class="modin add" type="text" placeholder={c.add.ph} list={c.add.gear ? 'mrgear' : undefined} {...c.id} data-modadd disabled={c.off} title={c.add.tip}>{/if}{#if c.gear}<GearList />{/if}</div>{:else if c.k === 'rows'}<div class="mrwrap"><table class="mrtbl"><thead><tr>{#each c.cols as col (col.k)}<th class="k-{col.kind}">{col.title}</th>{/each}<th></th></tr></thead><tbody>{#each c.rows as r, i (i)}<tr class="{r.fresh ? 'new' : ''} {r.unfilled ? 'unfilled' : ''}">{#each r.cells as x, j (j)}<td class="k-{c.cols[j]!.kind}">{#if x.k === 'slot'}<select class="modin" data-rowcell="{i}:{c.cols[j]!.k}" {...c.id} disabled={c.off} title={x.tip} use:selSync={(x.options.find(o => o.selected) || {value: ''}).value}>{#if x.empty}<option value=""></option>{/if}{#each x.options as o (o.value)}<option value={o.value} selected={o.selected}>{o.label}</option>{/each}</select>{:else if x.k === 'num'}<input class="modin num" type="text" inputmode="decimal" value={x.value} data-rowcell="{i}:{c.cols[j]!.k}" {...c.id} disabled={c.off} title={x.tip}>{:else}<span class="mrname">{@html x.icoHtml}<input class="modin" type="text" value={x.value} list={x.gear ? 'mrgear' : undefined} data-rowcell="{i}:{c.cols[j]!.k}" {...c.id} disabled={c.off} title={x.tip}></span>{/if}</td>{/each}<td class="mract">{#if r.unfilled}<i title={c.fillTip}>{c.fill}</i>{/if}{#each c.acts as a (a.what)}<button {...{['data-row' + a.what]: String(i)}} {...c.id} disabled={c.off || (a.what === 'up' && !i) || (a.what === 'down' && i >= c.rows.length - 1)} title={a.tip} aria-label={a.aria}>{a.sign}</button>{/each}</td></tr>{/each}</tbody></table>{#if c.add.pick}<button class="modaddbtn" data-modpick data-rowpick {...c.id} disabled={c.off} title={c.add.tip}>{c.add.label}</button>{:else}<button class="modaddbtn" data-rowadd {...c.id} disabled={c.off} title={c.add.tip}>{c.add.label}</button>{/if}{#if c.gear}<GearList />{/if}</div>{:else if c.k === 'multi'}{#each c.parts as p, i (i)}<ModCtl c={p} />{/each}{:else}<details class="modadv"><summary>{c.summary}</summary><pre class="modcode">{c.code}</pre></details>{/if}
